import Foundation

// MARK: - Blockchain Storage Layer
class BlockchainStorage {
    private let baseDir: String
    private var contractState: [String: Data] = [:]

    init(baseDir: String) {
        self.baseDir = baseDir
    }

    func resolveStoragePath(contractId: String, key: String) -> String {
        let normalized = normalizeKey(key)
        return baseDir + "/contracts/" + contractId + "/" + normalized
    }

    private func normalizeKey(_ key: String) -> String {
        // Remove null bytes and control characters
        let cleaned = key.filter { $0.asciiValue ?? 0 >= 0x20 && $0.asciiValue ?? 0 < 0x7F }
        // Collapse repeated separators
        let collapsed = cleaned.replacingOccurrences(of: "//", with: "/")
        return collapsed
    }

    func readState(path: String) -> Data? {
        return contractState[path] ?? (try? Data(contentsOf: URL(fileURLWithPath: path)))
    }

    func writeState(path: String, data: Data) {
        contractState[path] = data
        try? data.write(to: URL(fileURLWithPath: path))
    }
}

// MARK: - Role-Based Access Control
enum Role: Int, Comparable {
    case viewer = 0
    case editor = 1
    case admin = 2
    case owner = 3

    static func < (lhs: Role, rhs: Role) -> Bool {
        return lhs.rawValue < rhs.rawValue
    }
}

struct AccessPolicy {
    let requiredRole: Role
    let allowedPrefixes: [String]

    func authorize(userRole: Role, resourcePath: String) -> Bool {
        guard userRole >= requiredRole else { return false }
        let canonicalResource = canonicalizePath(resourcePath)
        return allowedPrefixes.contains { prefix in
            canonicalResource.hasPrefix(prefix)
        }
    }

    private func canonicalizePath(_ path: String) -> String {
        // Resolve . and .. components for authorization check
        var components = path.split(separator: "/").map(String.init)
        var resolved: [String] = []
        for component in components {
            if component == "." {
                continue
            } else if component == ".." {
                if !resolved.isEmpty { resolved.removeLast() }
            } else {
                resolved.append(component)
            }
        }
        return resolved.joined(separator: "/")
    }
}

// MARK: - Smart Contract Engine
class SmartContractEngine {
    private let storage: BlockchainStorage
    private var policies: [String: AccessPolicy] = [:]
    private var userRoles: [String: Role] = [:]

    init(storageBase: String) {
        self.storage = BlockchainStorage(baseDir: storageBase)
    }

    func registerUser(_ userId: String, role: Role) {
        userRoles[userId] = role
    }

    func setPolicy(contractId: String, policy: AccessPolicy) {
        policies[contractId] = policy
    }

    func executeStateRead(userId: String, contractId: String, stateKey: String) -> Data? {
        guard let role = userRoles[userId] else { return nil }
        guard let policy = policies[contractId] else { return nil }

        // Authorization check uses canonicalized path
        let authPath = contractId + "/" + stateKey
        guard policy.authorize(userRole: role, resourcePath: authPath) else {
            return nil
        }

        // Storage resolution uses normalized (but not canonicalized) path
        let storagePath = storage.resolveStoragePath(contractId: contractId, key: stateKey)
        return storage.readState(path: storagePath)
    }

    func executeStateWrite(userId: String, contractId: String, stateKey: String, value: Data) -> Bool {
        guard let role = userRoles[userId] else { return false }
        guard let policy = policies[contractId] else { return false }

        let authPath = contractId + "/" + stateKey
        guard policy.authorize(userRole: role, resourcePath: authPath) else {
            return false
        }

        let storagePath = storage.resolveStoragePath(contractId: contractId, key: stateKey)
        storage.writeState(path: storagePath, data: value)
        return true
    }
}

// MARK: - Contract Deployment Interface
class ContractDeployer {
    private let engine: SmartContractEngine

    init(engine: SmartContractEngine) {
        self.engine = engine
    }

    func deployContract(ownerId: String, contractId: String, allowedKeys: [String]) {
        engine.registerUser(ownerId, role: .owner)
        let policy = AccessPolicy(
            requiredRole: .editor,
            allowedPrefixes: allowedKeys.map { contractId + "/" + $0 }
        )
        engine.setPolicy(contractId: contractId, policy: policy)
    }

    func grantAccess(userId: String, role: Role) {
        engine.registerUser(userId, role: role)
    }
}

// MARK: - Usage Example
let engine = SmartContractEngine(storageBase: "/var/blockchain")
let deployer = ContractDeployer(engine: engine)

deployer.deployContract(ownerId: "alice", contractId: "token_contract", allowedKeys: ["balances", "metadata"])
deployer.grantAccess(userId: "bob", role: .editor)

// Bob can read within allowed prefixes
let _ = engine.executeStateRead(userId: "bob", contractId: "token_contract", stateKey: "balances/bob")
